"""Final website recertification inputs; historical evidence remains untouched."""
import json, os, statistics
from pathlib import Path
E=Path(__file__).resolve().parents[2]/'nift-benchmarks/lab-evidence'
SERIES='20261015-v4120-final-c14d068'
OFFICIAL=E/'benchmarks/website-generator'/SERIES/'official-refresh'
SUPPLEMENT=E/'campaigns/20261015-website-supplement-c14d068'
REV=os.environ.get('NIFT_WEBSITE_EVIDENCE_REVISION','19e390183b9bcb039abe6aa553ad88a2305b49ee')
def link(path,label):
 return f'<a href="https://github.com/nift-experiments/lab-evidence/blob/{REV}/{path}">{label}</a>'
def load(name):
 d=json.loads((OFFICIAL/name).read_text())
 assert d['publishable'] and d['jobs']
 for j in d['jobs']:
  samples=[s for s in j['samples'] if not s['warmup']]
  assert len(samples)==5 and all(s['correct'] for s in j['samples'])
  assert statistics.median(s['wall_ms'] for s in samples)==j['summary']['median_ms']
 return d
def supplement(p,table,section,figure,f):
 d=json.loads((SUPPLEMENT/'ANALYSIS-v3.json').read_text())['main'];rows=[]
 for engine in ('Nift','Hugo'):
  for mode in ('fresh','warm-full'):
   x=d[engine][mode];rows.append([engine,mode,f(x['median_ms']/1000),f(x['min_ms']/1000)+'–'+f(x['max_ms']/1000),f(x['median_cpu_ms']/1000),f(x['cpu_wall_percent']),f(x['median_peak_rss_kib']/1024)])
 body=p('A separate, audited defaults-only cohort uses all four logical CPUs: Nift build-threads=-1 and Hugo with GOMAXPROCS unset. Five measured builds plus one warmup per cell; 24 observations. These are not pooled with the CPU-0 campaign, observer controls or earlier scaling attempts.')
 body+=figure('website-generator','default-allcore',['Nift','Hugo'],{mode:[d[n][mode]['median_ms']/1000 for n in ('Nift','Hugo')] for mode in ('fresh','warm-full')},'Nift v4.12 final: normal all-core builds — 10,000 pages','Median wall seconds')
 body+=table(['Generator','State','Median s','Min–max s','CPU s','CPU/wall %','RSS MiB'],rows,'Separate defaults-only cohort; wall and CPU are distinct costs; RSS is waited-child high-water')
 official={j['id']:j['summary'] for j in load('website-10000.json')['jobs']}; targets={j['id']:j['summary'] for j in load('targeted-builds.json')['jobs']}
 body+=figure('website-generator','incremental-workflow',['No-op','One-page edit','Targeted leaf'],{'Nift v4.12 final':[official['Nift/incremental/no-op']['median_ms']/1000,official['Nift/incremental/one-page']['median_ms']/1000,targets['Nift/10000/targeted-one-page']['median_ms']/1000]},'Current Nift development workflow — CPU0 cohorts','Median wall seconds')
 body+=table(['Current workflow','Median s','Cohort'],[['No-op',f(official['Nift/incremental/no-op']['median_ms']/1000),'Official CPU0'],['One-page edit',f(official['Nift/incremental/one-page']['median_ms']/1000),'Official CPU0'],['Targeted leaf',f(targets['Nift/10000/targeted-one-page']['median_ms']/1000),'Separate serial CPU0']], 'Nift v4.12 final incremental workflow; distinct current cohorts, no peer ranking')
 body+=p('These current incremental measurements use CPU0, with the explicit target measured in its separate serial cohort. They are not all-core measurements and have no matched Hugo incremental comparison.')
 body+=p('Nift used about 27% less fresh wall time and 44% less warm wall time here. Fresh ranges overlap (Nift faster in four of five matched rounds); warm ranges do not overlap. Nift’s fresh total CPU time was slightly higher despite its shorter wall time. CPU/wall can exceed 100% with parallel workers; this is aggregate child CPU divided by wall time, not a worker-count measurement.')
 body+=p('Separate 50 ms process sampling found median maximum target OS-thread counts of five for Nift and seven for Hugo, with one product process each. OS threads are not simultaneously active workers. Sampling and GNU-time controls are separate from the headline cohort; their wall clocks include observer/polling overhead. A separate second-host default-fresh subset measured Nift 1.089 s and Hugo 1.461 s, versus 1.194 s and 1.636 s above; hosts are not pooled.')
 body+=p('Untimed fixture accounting found 10,001 additional Nift internal files totaling 6,584,541 bytes beyond public HTML. Both systems produced the expected 10,000-page semantic corpus; Nift HTML totaled 1,317,780 bytes and Hugo 1,327,780 bytes (one extra newline per page). Nift’s tracked JSON/templates and Hugo’s Markdown/frontmatter pipeline do different parsing and metadata work. This byte count does not identify a millisecond share of the fresh gap.')
 body+=p('The observed Nift fresh–warm difference was 390.725 ms. Exact-source inspection and separate strace runs support a retained-metadata mechanism: identical internal files can be checked and have timestamps refreshed rather than recreated atomically. Public HTML is removed and rewritten in both full-build states. Profiled fresh/warm write counts were 20,002/10,001; warm had more total syscalls, so syscall count alone is not cost. Separate software-CPU profiles had no lost samples; kernel filesystem/path/locking work was visible, while stripped Hugo symbols limit user-code attribution. No precise rendering/GC/metadata time decomposition is claimed.')
 body+=p('Host/environment sensitivity and identical-binary historical replay are documented in the linked evidence findings; historical result series are not displayed on this current report.')
 body+=p(link('campaigns/20261015-website-supplement-c14d068/EMPIRICAL-FINDINGS.md','Supplement findings and limitations')+' · '+link('campaigns/20261015-website-supplement-c14d068/ANALYSIS-v3.json','Exact cohort distributions')+' · '+link('campaigns/20261015-website-supplement-c14d068/OUTPUT-ORACLE-AUDIT.json','Independent output audit')+'. Earlier amended-plan observations, observer controls, telemetry and all eight instrumented profiles remain retained separately.')
 return section('Supplemental normal all-core cohort','Normal all-core builds: the practical comparison.',body,'parallel')
def machine_and_evidence(p,section):
 body=p('Official campaign: dedicated g6-standard-4, 8 GB / four vCPUs, AMD EPYC 7642, Ubuntu 24.04; timed processes pinned to CPU 0. Nift 4.12.0 source c14d06835bca515a5281e41da0e40219c2d60ef0, GCC 13.3, native Make -O2; CLI SHA-256 7dd42dcee5ca4a6965f0823c0ae59198282da1eb77e0fcd4cae93a537870a6fb. Hugo 0.167.0, Astro 7.3.6, VitePress 1.6.4 and Node 24.21.0. The separate all-core diagnostic retains its own host identities and raw observations.')
 body+=p('The frozen official plan passed independent audit: 39 jobs, 195 measured samples and 39 warmups (234 observations), including the separate serial targeted-build cohort. Full corpus output gates and incremental byte-parity checks passed. Historical series remain in lab-evidence; this page displays final v4.12 only.')
 body+=p(link(f'benchmarks/website-generator/{SERIES}/independent-audit.json','Official independent audit')+' · '+link(f'benchmarks/website-generator/{SERIES}/normalized-current-metrics.json','Normalized measurements')+' · '+link(f'benchmarks/website-generator/{SERIES}/official-refresh/website-10000.json','10,000-page raw observations')+' · '+link(f'benchmarks/website-generator/{SERIES}/official-refresh/targeted-builds.json','Targeted raw observations')+'. '+link(f'benchmarks/website-generator/{SERIES}/refresh-readiness.json','Frozen tool/source identities')+'.')
 return section('Frozen identity','One release candidate; explicit measurement boundaries.',body,'machine')+section('Reproduce / scrutinise','Retained raw observations and independent checks.',p(link(f'benchmarks/website-generator/{SERIES}','Complete accepted series')+' · <a href="https://github.com/nift-experiments/website-generator-benchmark/tree/a2890bc504cf7c55b77cd4fddae17403b7caf8ae">Exact suite source</a>. No benchmark rerun is needed to regenerate these presentation tables.'),'reproduce')
def opinion(p,section):
 return section('Practitioner judgement / AI-DX','Explicit contracts are useful work.',p('For an existing conventional Hugo/theme estate, staying with Hugo is sensible when its conventions already fit. For a new site, these measurements alone do not establish a universal platform choice; I prefer Nift here for mixed procedural, human-plus-agent and agent-primary workflows when its APIs and explicit tracking are maintained. Named targets, artifact ownership, input/template mappings and programmable .f policy make intent inspectable; extra metadata is not automatically redundant ceremony.')+p('These are qualitative preferences, not measured authoring/error rates. The harness checked complete routes, semantic contents, full-rebuild parity and unchanged unrelated pages; those checks are not universal product-native guarantees. This campaign did not compare Hugo incremental recovery or establish comprehensive structured build diagnostics for either tool. Parallel throughput strengthens Nift’s case here without erasing the official single-CPU result.'),'practitioner')
